function esc(s){return String(s==null?"":s).replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;");}
function val(v){return (v==null||v==="")?"-":esc(v);}
function rowsHtml(pairs){return pairs.map(function(p){return '<div class="row"><div class="k">'+esc(p[0])+'</div><div class="v">'+p[1]+'</div></div>';}).join('');}
function render(){
  var a=(appsmith.model&&appsmith.model.a)||{};
  var area=(a.area==null||a.area==="")?"-":(esc(a.area)+" Sq. Ft.");
  var opstat=a.operating_status?(String(a.operating_status).toLowerCase()==='active'?'Operational':esc(a.operating_status)):'-';
  var main=[["Description",val(a.description)],["Address",val(a.address)],["Postcode",val(a.postcode)],["Type",val(a.type)],["Area (Sq. Ft.)",area]];
  var addl=[["Site number",val(a.site_number)],["City",val(a.city)],["State",val(a.state)],["Country",val(a.country)],["Division",val(a.division)],["Phone",val(a.phone)],["Fax",val(a.fax)],["Latitude",val(a.latitude)],["Longitude",val(a.longitude)],["Operating status",opstat]];
  var custKeys=["Property","Premise number","Xref Number","Bldg#=Unit#","Floor plan","Unit #","Year Built","Location Level - GL Code","Legal Entity Name","Location Type","Energy Efficiency Upgrade","LED retrofit date","Location Classification","Property Name","Company Code"];
  var cust=custKeys.map(function(k){return [k,"-"];});
  var active=String(a.weather||"").toLowerCase()==="active";
  var weatherVal='<span class="dot" style="background:'+(active?'#22c55e':'#94a3b8')+'"></span>'+val(a.weather);
  var html='<div class="wrap">'
    +'<div class="col"><div class="sec">Main Information</div>'+rowsHtml(main)
      +'<div class="sec">Additional Information</div>'+rowsHtml(addl)+'</div>'
    +'<div class="col"><div class="sec">Custom Attributes</div>'+rowsHtml(cust)
      +'<div class="sec">Weather Data</div>'+rowsHtml([["Location weather data",weatherVal]])+'</div>'
    +'</div>';
  var root=document.getElementById("root");if(!root)return;root.innerHTML=html;
}
appsmith.onReady(function(){render();appsmith.onModelChange(render);});

